import serialize from "../common/url_serialize.js";

type AjaxMethod = "GET" | "POST" | "PUT" | "DELETE";

type AjaxCallback = (response: {
	xmlDoc: XMLHttpRequest;
	filePath: string;
}) => void;

type AjaxHeaders = Record<string, string>;

interface AjaxConfig {
	method: AjaxMethod;
	url: string;
	async?: boolean;
	data?: string;
	callback?: AjaxCallback;
	headers?: AjaxHeaders;
}

interface SchedulerAjax {
	cache: boolean;
	method: string;
	serializeRequestParams: typeof serialize;
	parse(data: string | Document): Document | string;
	xmltop(tagname: string, xhr: XMLHttpRequest, obj?: unknown): Element;
	xpath(xpathExp: string, docObj: Document | XMLHttpRequest): Node[];
	query(config: AjaxConfig): Promise<XMLHttpRequest>;
	get(
		url: string,
		onLoad?: AjaxCallback,
		headers?: AjaxHeaders,
	): Promise<XMLHttpRequest>;
	getSync(url: string, headers?: AjaxHeaders): Promise<XMLHttpRequest>;
	put(
		url: string,
		postData?: unknown,
		onLoad?: AjaxCallback,
		headers?: AjaxHeaders,
	): Promise<XMLHttpRequest>;
	del(
		url: string,
		onLoad?: AjaxCallback,
		headers?: AjaxHeaders,
	): Promise<XMLHttpRequest>;
	post(
		url: string,
		postData?: unknown,
		onLoad?: AjaxCallback,
		headers?: AjaxHeaders,
	): Promise<XMLHttpRequest>;
	postSync(
		url: string,
		postData?: unknown,
		headers?: AjaxHeaders,
	): Promise<XMLHttpRequest>;
	_call(
		method: AjaxMethod,
		url: string,
		postData: string | null,
		async: boolean,
		onLoad?: AjaxCallback,
		headers?: AjaxHeaders,
	): Promise<XMLHttpRequest>;
	urlSeparator(str: string): "?" | "&";
}

function stringifyData(data: unknown): string {
	if (!data) return "";
	return typeof data === "string" ? data : serialize(data);
}

function createConfig(method: AjaxMethod, args: IArguments): AjaxConfig {
	const params = Array.from(args);

	if (params.length === 0) {
		throw new Error("Arguments list of query is wrong.");
	}

	const result: AjaxConfig = {
		method,
		url: "",
	};

	if (params.length === 1) {
		const firstArg = params[0];

		if (typeof firstArg === "string") {
			result.url = firstArg;
			result.async = true;
		} else {
			result.url = firstArg.url;
			result.async = firstArg.async ?? true;
			result.callback = firstArg.callback;
			result.headers = firstArg.headers;
		}

		if (method === "POST" || method === "PUT") {
			result.data = stringifyData((firstArg as AjaxConfig).data);
		}

		return result;
	}

	result.url = params[0] as string;

	switch (method) {
		case "GET":
		case "DELETE":
			result.callback = params[1] as AjaxCallback;
			result.headers = params[2] as AjaxHeaders;
			break;

		case "POST":
		case "PUT":
			result.data = stringifyData(params[1]);
			result.callback = params[2] as AjaxCallback;
			result.headers = params[3] as AjaxHeaders;
			break;
	}

	return result;
}

export default function extend(scheduler: any): void {
	scheduler.Promise =
		typeof window !== "undefined" ? window.Promise : Promise;

	const ajax: SchedulerAjax = {
		cache: true,

		method: "get",

		serializeRequestParams: serialize,

		parse(data: string | Document): Document | string {
			if (typeof data !== "string") return data;

			let obj: Document | undefined;
			const xmlText = data.replace(/^[\s]+/, "");

			if (typeof DOMParser !== "undefined" && !scheduler.$env.isIE) {
				obj = new DOMParser().parseFromString(xmlText, "text/xml");
			} else if (
				typeof window !== "undefined" &&
				typeof window.ActiveXObject !== "undefined"
			) {
				obj = new window.ActiveXObject("Microsoft.XMLDOM");
				(obj as any).async = "false";
				(obj as any).loadXML(xmlText);
			}

			return obj || xmlText;
		},

		xmltop(tagname: string, xhr: XMLHttpRequest, obj?: unknown): Element {
			if (typeof xhr.status === "undefined" || xhr.status < 400) {
				const xml = !xhr.responseXML
					? this.parse(xhr.responseText || (xhr as unknown as string))
					: xhr.responseXML;

				if (
					typeof xml !== "string" &&
					xml.documentElement !== null &&
					!xml.getElementsByTagName("parsererror").length
				) {
					return xml.getElementsByTagName(tagname)[0];
				}
			}

			if (obj !== -1) {
				scheduler.callEvent("onLoadXMLError", [
					"Incorrect XML",
					xhr,
					obj,
				]);
			}

			return document.createElement("DIV");
		},

		xpath(xpathExp: string, docObj: Document | XMLHttpRequest): Node[] {
			const documentObject =
				"nodeName" in docObj ? docObj : docObj.responseXML || docObj;

			if (scheduler.$env.isIE) {
				return (documentObject as any).selectNodes?.(xpathExp) || [];
			}

			const rows: Node[] = [];
			const ownerDocument =
				(documentObject as any).ownerDocument || documentObject;
			const collection = ownerDocument.evaluate(
				xpathExp,
				documentObject,
				null,
				XPathResult.ANY_TYPE,
				null,
			);

			while (true) {
				const first = collection.iterateNext();

				if (first) {
					rows.push(first);
				} else {
					break;
				}
			}

			return rows;
		},

		query(config: AjaxConfig): Promise<XMLHttpRequest> {
			return this._call(
				config.method || "GET",
				config.url,
				String(config.data || ""),
				config.async ?? true,
				config.callback,
				config.headers,
			);
		},

		get(
			url: string,
			onLoad?: AjaxCallback,
			headers?: AjaxHeaders,
		): Promise<XMLHttpRequest> {
			const config = createConfig("GET", arguments);
			return this.query(config);
		},

		getSync(url: string, headers?: AjaxHeaders): Promise<XMLHttpRequest> {
			const config = createConfig("GET", arguments);
			config.async = false;
			return this.query(config);
		},

		put(
			url: string,
			postData?: unknown,
			onLoad?: AjaxCallback,
			headers?: AjaxHeaders,
		): Promise<XMLHttpRequest> {
			const config = createConfig("PUT", arguments);
			return this.query(config);
		},

		del(
			url: string,
			onLoad?: AjaxCallback,
			headers?: AjaxHeaders,
		): Promise<XMLHttpRequest> {
			const config = createConfig("DELETE", arguments);
			return this.query(config);
		},

		post(
			url: string,
			postData?: unknown,
			onLoad?: AjaxCallback,
			headers?: AjaxHeaders,
		): Promise<XMLHttpRequest> {
			let currentPostData = postData;
			let currentOnLoad = onLoad;

			if (arguments.length === 1) {
				currentPostData = "";
			} else if (
				arguments.length === 2 &&
				typeof currentPostData === "function"
			) {
				currentOnLoad = currentPostData as AjaxCallback;
				currentPostData = "";
			}

			const config = createConfig("POST", [
				url,
				currentPostData,
				currentOnLoad,
				headers,
			] as unknown as IArguments);
			return this.query(config);
		},

		postSync(
			url: string,
			postData?: unknown,
			headers?: AjaxHeaders,
		): Promise<XMLHttpRequest> {
			const currentPostData = postData === null ? "" : String(postData);

			const config = createConfig("POST", [
				url,
				currentPostData,
				headers,
			] as unknown as IArguments);
			config.async = false;

			return this.query(config);
		},

		_call(
			method: AjaxMethod,
			url: string,
			postData: string | null,
			async: boolean,
			onLoad?: AjaxCallback,
			headers?: AjaxHeaders,
		): Promise<XMLHttpRequest> {
			return new scheduler.Promise((resolve: any) => {
				let xhr: XMLHttpRequest =
					typeof XMLHttpRequest !== "undefined" &&
					!scheduler.$env.isIE
						? new XMLHttpRequest()
						: new window.ActiveXObject("Microsoft.XMLHTTP");

				const userAgent =
					typeof navigator !== "undefined" ? navigator.userAgent : "";
				const isQt =
					userAgent.match(/AppleWebKit/) !== null &&
					userAgent.match(/Qt/) !== null &&
					userAgent.match(/Safari/) !== null;

				if (async) {
					xhr.addEventListener("readystatechange", () => {
						if (
							xhr.readyState === 4 ||
							(isQt && xhr.readyState === 3)
						) {
							if (xhr.status !== 200 || xhr.responseText === "") {
								if (!scheduler.callEvent("onAjaxError", [xhr]))
									return;
							}

							setTimeout(() => {
								if (typeof onLoad === "function") {
									onLoad.apply(window, [
										{ xmlDoc: xhr, filePath: url },
									]);
								}

								resolve(xhr);
							}, 0);
						}
					});
				}

				let requestUrl = url;

				if (method === "GET" && !this.cache) {
					requestUrl += `${requestUrl.indexOf("?") >= 0 ? "&" : "?"}dhxr${Date.now()}=1`;
				}

				xhr.open(method, requestUrl, async);

				if (headers) {
					for (const key in headers) {
						xhr.setRequestHeader(key, headers[key]);
					}
				} else if (
					method === "POST" ||
					method === "PUT" ||
					method === "DELETE"
				) {
					xhr.setRequestHeader(
						"Content-Type",
						"application/x-www-form-urlencoded",
					);
				} else if (method === "GET") {
					postData = null;
				}

				xhr.setRequestHeader("X-Requested-With", "XMLHttpRequest");
				xhr.send(postData);

				if (!async) {
					resolve(xhr);
				}
			});
		},

		urlSeparator(str: string): "?" | "&" {
			return str.indexOf("?") !== -1 ? "&" : "?";
		},
	};

	scheduler.ajax = ajax;
	scheduler.$ajax = scheduler.ajax;
}
